export function tokenize(book){const words=[];const chapters=[];let paragraph=0;for(const ch of book.chapters){const start=words.length;for(const text of ch.paragraphs){const tokens=text.trim().split(/\s+/u).filter(Boolean);tokens.forEach((text,i)=>words.push({text,paragraph,chapter:chapters.length,end:i===tokens.length-1}));paragraph++;}if(words.length>start)chapters.push({title:ch.title,start,end:words.length-1});}return {words,chapters};}
export function focalIndex(word){const chars=Array.from(word);const start=chars.findIndex(c=>/[\p{L}\p{N}]/u.test(c));if(start<0)return 0;const letters=chars.filter(c=>/[\p{L}\p{N}]/u.test(c)).length;return Math.min(chars.length-1,start+(letters<=1?0:letters<=5?1:letters<=9?2:letters<=13?3:4));}
export function sentenceEnd(word){return /[.!?…]["'’”»)\]]*$/u.test(word.text)||word.end;}
export function sentenceJump(words,index,direction){if(direction>0){let i=index;while(i<words.length-1&&!sentenceEnd(words[i]))i++;return Math.min(words.length-1,i+1);}let i=Math.max(0,index-1);while(i>0&&!sentenceEnd(words[i-1]))i--;if(i===index&&i>0){i--;while(i>0&&!sentenceEnd(words[i-1]))i--;}return i;}
export function delayFor(words,speed,pauses){let delay=60000/speed*words.length;if(pauses){const last=words.at(-1);if(sentenceEnd(last))delay*=1.8;else if(/[,;:]["'’”)]*$/u.test(last.text))delay*=1.3;}return delay;}
// EPUB is a ZIP container. Use the central directory so data descriptors are supported.
export async function unzip(buffer){const view=new DataView(buffer),bytes=new Uint8Array(buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(view.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('This file is not a valid EPUB archive.');const count=view.getUint16(end+10,true);if(count>3000)throw Error('This EPUB has too many entries.');let pos=view.getUint32(end+16,true),total=0;const files=new Map(),decode=new TextDecoder();for(let i=0;i<count;i++){if(view.getUint32(pos,true)!==0x02014b50)throw Error('Invalid EPUB directory.');const flags=view.getUint16(pos+8,true),method=view.getUint16(pos+10,true),compressed=view.getUint32(pos+20,true),size=view.getUint32(pos+24,true),nameLength=view.getUint16(pos+28,true),extra=view.getUint16(pos+30,true),comment=view.getUint16(pos+32,true),offset=view.getUint32(pos+42,true),name=decode.decode(bytes.slice(pos+46,pos+46+nameLength));pos+=46+nameLength+extra+comment;total+=size;if(total>80*1024*1024)throw Error('This EPUB expands beyond the 80 MB limit.');if(flags&1)throw Error('Encrypted EPUBs are not supported.');if(name.endsWith('/'))continue;files.set(name,async()=>{const start=offset+30+view.getUint16(offset+26,true)+view.getUint16(offset+28,true);const chunk=bytes.slice(start,start+compressed);if(method===0)return decode.decode(chunk);if(method!==8)throw Error('Unsupported EPUB compression.');let stream;try{stream=new DecompressionStream('deflate-raw');}catch{throw Error('EPUB import needs a recent Safari, Chrome or Firefox. You can still use Carmen or paste text.');}const output=await new Response(new Blob([chunk]).stream().pipeThrough(stream)).arrayBuffer();if(output.byteLength!==size)throw Error('Damaged EPUB entry.');return decode.decode(output);});}return files;}
